              </div>
              {isPaid ? null : (
                <button
                  type="button"
                  data-testid="pay-button"
                  onClick={() => handlePay(bill.id)}
                  className="w-full rounded-md bg-slate-900 px-3 py-2 text-sm font-medium text-white hover:bg-slate-700 md:w-auto"
                >
                  {isRecurring ? "Mark occurrence paid" : "Mark paid"}
                </button>
              )}
            </div>
          );
        })}
      </div>
    </section>
  );
}

